 "Natural hazards and climate":[["Severe weather or flooding","Premises, transport, utilities and staff access may be disrupted for an extended period."],["Extreme heat or cold","Unsafe working conditions, equipment limitations and utility demand may reduce operational capacity."],["Long-term climate change exposure","Increasing hazard frequency may make existing locations, suppliers or controls insufficient."]],
 "Market and competitive pressure":[["Loss of major customer or contract","Revenue and resource reductions may affect the viability of priority services and resilience investment."],["Rapid change in customer expectations","Existing capacity, channels or recovery targets may no longer meet customer needs."],["Competitor or substitute disruption","Market shifts may require rapid operational change while continuity resources are constrained."]],
 "Utilities and energy security":[["Electricity supply interruption","Technology, equipment, environmental controls and site operations may stop without adequate backup."],["Gas, water or fuel shortage","Essential facilities, production or welfare arrangements may become unavailable."],["Energy price or capacity constraint","Operating hours, production capacity or recovery arrangements may need to be reduced."]],
 "Supply-chain and geopolitical disruption":[["Critical supplier failure","Essential materials, services or specialist support may be unavailable within required recovery times."],["Transport or border disruption","Inbound supplies and outbound customer deliveries may be delayed or stopped."],["Conflict or geopolitical instability","People, sites, suppliers, payments and communications in affected regions may become unavailable."],["Single-source dependency","Failure of one provider may stop a priority process because no proven alternative exists."]],
 "Governance and decision rights":[["Unclear emergency authority","Decisions and escalation may be delayed because response authority is not defined."],["Leadership unavailability","Strategic decisions, approvals and external communications may be delayed."],["Fragmented governance across sites","Conflicting priorities may prevent coordinated response and recovery."]],
 "Organisational structure and roles":[["Unclear continuity roles","Essential response tasks may be missed, duplicated or delayed."],["Organisational restructure","Changed reporting lines and responsibilities may make plans and contact details obsolete."],["Dependence on one team or location","Loss of a single organisational unit may remove essential capacity."]],
 "Policies, objectives and strategy":[["Continuity priorities not aligned with strategy","Resources may be directed away from the services most important to organisational objectives."],["Outdated policies or plans","Personnel may follow obsolete requirements during disruption."],["Conflicting business objectives","Recovery decisions may be delayed by competing operational, financial or compliance priorities."]],
