 "Technology, data and knowledge":[["Unsupported critical system","Failure may take longer to restore because vendor support, parts or expertise are unavailable."],["Inadequate backup or restore capability","Critical data may be unavailable, incomplete or recovered too slowly."],["Undocumented specialist knowledge","Recovery may depend on individuals whose knowledge has not been transferred."]],
 "Culture and risk awareness":[["Low continuity awareness","Personnel may not recognise incidents, escalate promptly or follow recovery arrangements."],["Reluctance to report weaknesses","Emerging vulnerabilities may remain hidden until a disruption occurs."],["Poor learning from incidents and exercises","Known failures may recur because improvements are not completed or verified."]],
 "Contractual relationships":[["Unclear supplier continuity obligations","Providers may not deliver recovery support or information within required timescales."],["Customer recovery commitments exceed capability","Contractual service levels may be breached during disruption."],["Expired or incomplete agreements","Emergency access, alternative facilities or mutual support may not be legally available."]],
 "Facilities, equipment and utilities":[["Single-site dependency","Loss of the premises may stop priority services without a usable alternative location."],["Critical equipment failure","Operations may stop when replacement equipment, parts or maintenance are unavailable."],["Insufficient backup utilities","Loss of power, water, cooling or communications may exceed onsite resilience."]],
 "Financial resources and insurance":[["Insufficient emergency funding","Urgent recovery purchases, temporary facilities or specialist support may be delayed."],["Inadequate insurance coverage","Losses or recovery costs may exceed available financial resources."],["Payment or banking interruption","Payroll, supplier payments and essential purchases may be delayed."]]
